import sys

def main():
    input_lines = sys.stdin.read().splitlines()
    total = int(input_lines[0])
    s = input_lines[1].lower()
    original = s
    chArr = list(s)
    sb = list(original)
    stack = []
    for c in chArr:
        stack.append(c)
    bracketIndices = []
    for i, c in enumerate(chArr):
        if c == '(' or c == ')':
            stack.pop()
            bracketIndices.append(i)
    pairMap = {}
    for i in range(0, len(bracketIndices), 2):
        pairMap[bracketIndices[i]] = bracketIndices[i + 1]
    toRemoveIndices = []
    for startIdx, endIdx in pairMap.items():
        for i in range(startIdx, endIdx + 1):
            toRemoveIndices.append(i)
    removeSet = set(toRemoveIndices)
    filteredChars = [chArr[i] for i in range(len(chArr)) if i not in removeSet]
    replacedChars = []
    toggleFlag = True
    for i in range(len(chArr)):
        if i in removeSet:
            if chArr[i] in ['(', ')', '_']:
                if toggleFlag:
                    replacedChars.append(' ')
                    toggleFlag = False
            else:
                replacedChars.append(chArr[i])
                toggleFlag = True
    resultStr = ''.join(replacedChars)
    partsAfter = resultStr.split(" ")
    lengthAfter = []
    for p in partsAfter:
        trimmed = p.strip()
        if len(trimmed) != 0:
            lengthAfter.append(len(trimmed))
    replacedStr = s.replaceAll(r"\(.*?\) ?", " ").replace('_', ' ')
    partsBefore = replacedStr.split(" ")
    lengthBefore = []
    for p in partsBefore:
        trimmed = p.strip()
        if len(trimmed) != 0:
            lengthBefore.append(len(trimmed))
    lengthAfter.sort()
    maxLen = 0 if len(lengthAfter) == 0 else lengthAfter[-1]
    print(f"{maxLen} {len(lengthBefore)}")

